Neon Bars:
for (let i = 0; i < lv.length; i++) {
  const bw = w / lv.length, bh = lv[i] * h;
  g.fillStyle = 'hsl(' + (i / lv.length * 320) + ',90%,60%)';
  g.fillRect(i * bw + 1, h - bh, bw - 2, bh);
}

Heartbeat Line:
g.strokeStyle = accent; g.lineWidth = 3; g.beginPath();
for (let i = 0; i < lv.length; i++) {
  const x = i * w / lv.length, y = h / 2 - (i % 2 ? 1 : -1) * lv[i] * h * 0.45;
  i ? g.lineTo(x, y) : g.moveTo(x, y);
}
g.stroke();
